from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core import StartableCollector
from taf.collectors.core.entities.executor import ExecutionError
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SyscomdumpCollector(Using("tool_executor"), Using("file_getter"), StartableCollector):
    """
          To Start , Stop and Collect  syscomdump logs on given configuration.
    """

    def __init__(self,
                 options=None,
                 syscomdump_path="syscomdump",
                 stop_timeout=3,
                 container=None,
                 target_file_name=None,
                 **kwargs):
        super(SyscomdumpCollector, self).__init__(**kwargs)
        self._log_path = "/tmp/syscomdump_{name}.pcap".format(name=self._name)
        self._syscomdump_path = syscomdump_path
        self._target_file_name = target_file_name if target_file_name \
            else "{name}.pcap".format(name=self._name)
        self._options = " {options}".format(options=options) if options else ""
        self._sudo_prefix = None
        self._stop_timeout = stop_timeout
        self._container = container

    def _start(self):
        start_command = (
            "{lxc_prefix}'{syscomdump_path}' -w '{log_path}'{options}").format(
                log_path=self._log_path,
                lxc_prefix=self._lxc_prefix,
                syscomdump_path=self._syscomdump_path,
                options=self._options).encode()
        self._process = self._tool_executor.start(start_command, use_tty=True)

    def _stop(self):
        self._process.stdin.write("\x03".encode())
        self._wait_till_process_terminated()

    def _wait_till_process_terminated(self):
        self._process.wait(timeout=self._stop_timeout)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        self._set_lxc_prefix()
        self._process_and_file_cleanup()

    def _collect(self, target_dir):
        self._file_getter.get_file(
            source_path="/tmp/node_{container_id}{log_path}".format(
                container_id=self._container_id,
                log_path=self._log_path) if self._container else self._log_path,
            target_path="{target_dir}/{target_file_name}".format(target_dir=target_dir,
                                                                 target_file_name=self._target_file_name))

    def _teardown(self):
        self._process_and_file_cleanup()

    def _process_and_file_cleanup(self):
        try:
            self._tool_executor.execute(
                '{lxc_prefix}pkill -9 -f "{syscomdump_path} -w {log_path}"'.format(
                    syscomdump_path=self._syscomdump_path,
                    lxc_prefix=self._lxc_prefix,
                    log_path=self._log_path).encode())
        except ExecutionError as exception:
            logger.debug("Terminating %r process failed: %r", self._syscomdump_path, exception)
        self._file_cleanup()

    def _file_cleanup(self):
        self._tool_executor.execute('{sudo_prefix}rm -f "{container_path}{log_path}"'.format(
            sudo_prefix=self._sudo_prefix,
            container_path="" if not self._container else "/tmp/node_{container_id}".format(
                container_id=self._container_id),
            log_path=self._log_path).encode())

    def _set_lxc_prefix(self):
        if self._container:
            self._container_id = self._tool_executor.execute(
                "for i in $(lxc-ls) ; do echo \"$i $(lxc-attach -n $i -- uname -n)\" ;"
                " done | grep '{container}' | awk '{{print $1;}}'".format(
                    container=self._container).encode('utf-8')).strip().decode('utf-8')
            if self._container_id == "":
                raise Exception("Unable to fetch container_id with container_name "
                                "having substring '{container}'".format(container=self._container))
            self._lxc_prefix = "lxc-attach -n {container_id} -- ".format(container_id=self._container_id)
        else:
            self._lxc_prefix = ""
